import type { Campaign } from './campaign-model';
import type { Employee } from './employee-model';
import type { Participant } from './participant-model';

export const AssessmentStatusKeyToLabel = {
  'Draft': 'Draft',
  'Submitted': 'Submitted',
  'ManagerReview': 'Manager Review',
  'Finalized': 'Finalized',
  'Superseded': 'Superseded'
} as const;
export type AssessmentStatusKey = keyof typeof AssessmentStatusKeyToLabel;

export interface Assessment {
  /**
   * @displayName Assessment ID
   * @description Unique system identifier - GUID generated by system
   * @uiConstraints NEVER create input fields for this ID
   */
  id: string;
  /**
   * @displayName Assessment Name
   * @description Human-readable record identifier
   * @validationRule Required for create/update operations
   */
  assessmentName: string;
  /**
   * @displayName AI Report
   */
  aIReport?: string;
  /**
   * @displayName Campaign
   * @validationRule Required for create/update operations
   */
  campaign: Pick<Campaign, 'id' | 'campaignName'>;
  /**
   * @displayName Created Date
   * @validationRule Required for create/update operations
   */
  createdDate: string;
  /**
   * @displayName Employee
   * @validationRule Required for create/update operations
   */
  employee: Pick<Employee, 'id' | 'employeeName'>;
  /**
   * @displayName Final Report
   */
  finalReport?: string;
  /**
   * @displayName Latest Flag
   * @validationRule Required for create/update operations
   */
  latestFlag: boolean;
  /**
   * @displayName Manager
   * @validationRule Required for create/update operations
   */
  manager: Pick<Employee, 'id' | 'employeeName'>;
  /**
   * @displayName Participant
   * @validationRule Required for create/update operations
   */
  participant: Pick<Participant, 'id' | 'participantName'>;
  /**
   * @displayName Previous Assessment
   */
  previousAssessment?: Pick<Assessment, 'id' | 'assessmentName'>;
  /**
   * @displayName Status
   * @validationRule Required for create/update operations
   */
  statusKey: AssessmentStatusKey;
  /**
   * @displayName Submitted Date
   */
  submittedDate?: string;
  /**
   * @displayName Version Number
   * @validationRule Required for create/update operations
   */
  versionNumber: number;
}

export const _Assessment = 'Assessment' as const;